#include <iostream>

int main() {
    int age = 20;

    // Ternary operator: condition ? true_value : false_value
    std::string status = (age >= 18) ? "Adult" : "Minor";

    std::cout << "Status: " << status << std::endl;

    // Equivalent if-else (longer)
    std::string status2;
    if (age >= 18) {
        status2 = "Adult";
    } else {
        status2 = "Minor";
    }

    std::cout << "Status2: " << status2 << std::endl;

    return 0;
}

