#include <iostream>

int main() {
    // Count backwards from 5 to 1
    for (int i = 5; i >= 1; i--) {
        std::cout << i << " ";
    }
    std::cout << std::endl;

    // Count by 2s
    for (int i = 0; i <= 10; i += 2) {
        std::cout << i << " ";
    }
    std::cout << std::endl;

    // Multiple variables in for loop
    for (int i = 0, j = 10; i < j; i++, j--) {
        std::cout << "i=" << i << " j=" << j << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <iostream>

int main() {
    // break example
    std::cout << "break at 5: ";
    for (int i = 0; i < 10; i++) {
        if (i == 5) {
            break;
        }
        std::cout << i << " ";
    }
    std::cout << std::endl;

    // continue example
    std::cout << "skip 3: ";
    for (int i = 0; i < 6; i++) {
        if (i == 3) {
            continue;
        }
        std::cout << i << " ";
    }
    std::cout << std::endl;

    return 0;
}

